/**
 * @file gfifo_cfg.h
 * @brief GFIFO 编译期配置：功能裁剪、索引宽度、断言与内存清零策略
 * @author Ricardo
 * @date 2026-10-31
 *
 * @note 本文件是移植时唯一需要按平台调整的配置入口。所有配置项都用 #ifndef
 *       包裹，所以也可以一个字都不改，直接在编译命令行用 -D 覆盖，例如：
 *         -DGFIFO_CFG_INDEX_TYPE=uint16_t -DGFIFO_CFG_ENABLE_STATS=0
 *
 * @note 配置项一旦改动必须"全量重编译"（gfifo.c 与所有调用方一起重编），
 *       否则头文件里的 gfifo_t 布局会与库内部不一致，症状是"写进去读出来
 *       是乱码"或"明明调了 Init 却报未初始化"，极难排查。
 *
 * @note 本文件不 include 任何平台头文件，只依赖 <stdint.h>。
 */

#ifndef __GFIFO_CFG_H__
#define __GFIFO_CFG_H__

/*==============================================================================
 * 头文件包含
 *============================================================================*/
/* 固定包含 */
#include <stdint.h>

/*==============================================================================
 * 索引宽度
 *============================================================================*/

/**
 * @brief 环形缓冲的索引与计数器类型，决定单个 FIFO 的最大容量
 *
 * @note 选 uint32_t：适配所有 32 位 MCU（Cortex-M / RISC-V32 / ESP32），
 *       单 FIFO 容量上限 4 GiB，32 位对齐读写天然原子，SPSC 无锁成立。
 *
 * @note 选 uint16_t：给 8/16 位 MCU（8051 / MSP430 / AVR）或 RAM 极紧的
 *       场合省 6~10 字节。此时单 FIFO 容量上限 65535 字节，而且 16 位
 *       对齐读写在 16 位机上是原子的，SPSC 无锁同样成立。
 *
 * @note 选 uint64_t 没有意义：64 位读写在任何主流 MCU 上都不是原子的，
 *       反而必须依赖临界区。库不做限制，但不推荐。
 */
#ifndef GFIFO_CFG_INDEX_TYPE
#define GFIFO_CFG_INDEX_TYPE uint32_t
#endif

/*==============================================================================
 * 容量与索引策略
 *============================================================================*/

/**
 * @brief 是否强制 FIFO 容量为 2 的幂（1 = 强制，0 = 允许任意容量）
 *
 * @note 1：索引换算退化为 idx & (size - 1)，单条指令，无除法。
 *       代价是容量只能取 1/2/4/8/.../32768 这类值；结构体元素还要求
 *       size 同时是 elem_size 的整数倍，两个条件容易打架。
 *
 * @note 0（默认）：Init 时自动判断。容量恰好是 2 的幂就走掩码快路径，
 *       否则走 % 取模。代价是每次换算多一次分支，好处是 elem_size 为
 *       24、36 这类"非 2 的幂"的结构体也能把缓冲区用满、不浪费一个字节。
 *
 * @note 什么时候该设 1：容量固定、元素为字节流（elem_size == 1）、
 *       并且 DMA 搬运对时序极敏感。此时掩码路径比取模快 20~60 个周期/次。
 */
#ifndef GFIFO_CFG_POW2_ONLY
#define GFIFO_CFG_POW2_ONLY 0
#endif

/*==============================================================================
 * 功能裁剪
 *============================================================================*/

/**
 * @brief 是否编入统计计数（写入总量 / 读出总量 / 峰值水位 / 溢出 / 下溢）
 *
 * @note 1（默认）：每个 FIFO 句柄多占 5 * 4 = 20 字节 RAM，换来现场诊断能力。
 *       调试期强烈建议开着：现场"偶发丢数据"十有八九看峰值水位就能定位。
 *
 * @note 0：量产版省 RAM。此时所有 GFIFO_Stat_xxx() 恒返回 0，不会编译失败，
 *       所以可以同一份应用代码在调试版与量产版之间切换。
 */
#ifndef GFIFO_CFG_ENABLE_STATS
#define GFIFO_CFG_ENABLE_STATS 1
#endif

/**
 * @brief 是否编入"预留-提交"接口（GFIFO_Write_Reserve / Commit / Abort）
 *
 * @note 1（默认）：支持"先把空间占下来，再让 DMA 直接往里灌"的零拷贝写入，
 *       也支持变长消息层在无锁状态下拼装跨回绕点的帧。
 *
 * @note 0：句柄省 4 字节（rsv 字段仍在，但恒为 0），代码省约 600 字节 Flash。
 *       关闭后调用这三个函数返回 GFIFO_ERR_PARAM。
 */
#ifndef GFIFO_CFG_ENABLE_RESERVE
#define GFIFO_CFG_ENABLE_RESERVE 1
#endif

/**
 * @brief 是否编入变长消息接口（GFIFO_Msg_xxx）
 *
 * @note 1（默认）：在同一个环形缓冲上支持"不定长报文"，每条消息自带长度头，
 *       适合串口协议帧、日志行、事件包这类"长度不固定"的数据。
 *
 * @note 0：只保留字节流与定长元素两种用法，代码省约 900 字节 Flash。
 */
#ifndef GFIFO_CFG_ENABLE_MSG
#define GFIFO_CFG_ENABLE_MSG 1
#endif

/**
 * @brief 是否编入参数合法性检查（NULL / 未初始化 / 越界 / 元素错位）
 *
 * @note 1（默认）：每个入口多做 2~4 次比较，换来"传错参数立刻返回错误码"
 *       而不是把野指针写穿。开发阶段必须开。
 *
 * @note 0：量产且已充分验证后可关，省几个周期。关闭后传 NULL 会直接 HardFault，
 *       这是"用速度换安全"的自觉选择，不是库的缺陷。
 */
#ifndef GFIFO_CFG_ENABLE_PARAM_CHECK
#define GFIFO_CFG_ENABLE_PARAM_CHECK 1
#endif

/**
 * @brief 是否编入临界区支持（多生产者 / 多消费者场景）
 *
 * @note 0（默认）：所有操作都不加锁，只支持 SPSC（一个生产者、一个消费者）。
 *       这是嵌入式里 90% 的用法，实时性最好——中断不会被关，生产者与消费者
 *       互不等待。串口收发、ADC 采样、日志缓冲都属于这一类。
 *
 * @note 1：编入临界区调用。注意光把这一项设为 1 还不够，还必须在
 *       gfifo_port.h 里实现 GFIFO_ENTER_CRITICAL / GFIFO_EXIT_CRITICAL，
 *       并且在 GFIFO_Init 时给 flags 传入 GFIFO_FLAG_CRITICAL。
 *       三者缺一，标志就是个摆设，压力测试下会丢数据。
 *
 * @note 开启后的代价：每次读写都要进出一次临界区。关中断实现下，
 *       最坏中断响应时间会增加"一次拷贝 + 几条指令"，通常在 1~3 微秒。
 *       所以只在真的需要多生产者/多消费者时才开。
 */
#ifndef GFIFO_CFG_ENABLE_CRITICAL
#define GFIFO_CFG_ENABLE_CRITICAL 0
#endif

/*==============================================================================
 * 变长消息格式
 *============================================================================*/

/**
 * @brief GFIFO_Msg_xxx 的长度头字节数，只能是 1、2 或 4
 *
 * @note 1：单条消息上限 255 字节，每条消息额外开销 1 字节。适合 CAN 帧、
 *       短命令包这类小报文。
 *
 * @note 2（默认）：单条消息上限 65535 字节，额外开销 2 字节。覆盖面最广。
 *
 * @note 4：单条消息上限 4 GiB，额外开销 4 字节。几乎不需要，除非在跑
 *       大块文件传输。
 *
 * @note 长度头按"主机字节序"存放，不做网络序转换：FIFO 是同一颗 CPU
 *       内部的生产者与消费者之间的通道，跨设备通信应该由协议层负责字节序。
 */
#ifndef GFIFO_CFG_MSG_HDR_BYTES
#define GFIFO_CFG_MSG_HDR_BYTES 2
#endif

/*==============================================================================
 * 内存策略
 *============================================================================*/

/**
 * @brief 是否使用 <string.h> 的 memcpy / memset（1 = 用，0 = 用库内字节循环）
 *
 * @note 1（默认）：主流工具链的 memcpy 是汇编优化版，按字搬运，快 3~10 倍。
 *       只要链接了标准 C 库（几乎所有 MCU 工具链都带），就应该设 1。
 *
 * @note 0：用于 -nostdlib、Bootloader 早期、或安全认证要求"不引入任何
 *       外部符号"的场合。库内的字节循环会被现代编译器自动向量化，
 *       性能损失通常没有想象中大。
 */
#ifndef GFIFO_CFG_USE_LIBC
#define GFIFO_CFG_USE_LIBC 1
#endif

/**
 * @brief Init 时是否把整块缓冲区清零（1 = 清零，0 = 保留原内容）
 *
 * @note 1（默认）：清零有两个实际好处。一是零拷贝接口（GFIFO_Peek_Span）
 *       在 FIFO 为空时不会把上一轮残留的数据当成有效内容；二是上电后
 *       调试器里看到的缓冲区是干净的，"没写进去"和"写进去是 0"不会混淆。
 *
 * @note 0：省一次 O(size) 的 memset。大缓冲区（如 64 KiB 音频缓冲）在
 *       启动时间敏感时值得关掉，但要自己承担"读到残留数据"的风险。
 *
 * @note 也可以在单个 FIFO 上用 GFIFO_FLAG_NO_CLEAR 标志覆盖此项。
 */
#ifndef GFIFO_CFG_CLEAR_ON_INIT
#define GFIFO_CFG_CLEAR_ON_INIT 1
#endif

/*==============================================================================
 * 断言
 *============================================================================*/

/**
 * @brief 是否启用库内断言 GFIFO_ASSERT()
 *
 * @note 0（默认）：关闭。嵌入式发布版不应该因为一个参数错误就死循环，
 *       错误码已经能表达同样的事。
 *
 * @note 1：打开后，库在"绝不该发生"的分支上调用 GFIFO_ASSERT()，默认映射到
 *       <assert.h> 的 assert()，从而停在调试器里。开发阶段建议打开。
 *
 * @note 断言的具体实现可以在 gfifo_port.h 里用 GFIFO_ASSERT 宏覆盖，
 *       例如映射到 printf + while(1)，或映射到 RTOS 的 configASSERT。
 */
#ifndef GFIFO_CFG_ENABLE_ASSERT
#define GFIFO_CFG_ENABLE_ASSERT 0
#endif

/*==============================================================================
 * 配置合法性检查
 *============================================================================*/

/* 长度头只能是 1、2、4 字节；写成 3 会让编解码逻辑失去定义 */
#if (GFIFO_CFG_MSG_HDR_BYTES != 1) && \
    (GFIFO_CFG_MSG_HDR_BYTES != 2) && \
    (GFIFO_CFG_MSG_HDR_BYTES != 4)
#error "GFIFO_CFG_MSG_HDR_BYTES must be 1, 2 or 4"
#endif

/* 索引类型的宽度检查放 gfifo.h：那里有 GFIFO_STATIC_ASSERT 可用，
   预处理阶段无法对"类型"做比较，只能等编译器看到 typedef 之后再断言。 */

#endif /* __GFIFO_CFG_H__ */
